/**
 * SERVER-ONLY data loaders (Node fs access).
 * Never import this module from a client ("use client") component.
 */
import fs from "node:fs";
import path from "node:path";

import type { CourseSummary, CourseTopics, Crop } from "@/types";

const DATA_DIR = process.env.DATA_DIR || path.resolve(process.cwd(), "data");

/** Structured topic guides (generated by scripts/build-topics.mjs). */
let topicsCache: CourseTopics[] | null = null;

function loadTopics(): CourseTopics[] {
  if (topicsCache) return topicsCache;
  const file = path.join(DATA_DIR, "topics.json");
  if (!fs.existsSync(file)) return [];
  try {
    topicsCache = JSON.parse(fs.readFileSync(file, "utf8")) as CourseTopics[];
    return topicsCache;
  } catch {
    return [];
  }
}

export function getCourseTopics(slug: string): CourseTopics | undefined {
  return loadTopics().find((course) => course.slug === slug);
}

export function getCourseIndex(): CourseSummary[] {
  const raw = fs.readFileSync(path.join(DATA_DIR, "index.json"), "utf8");
  const courses = JSON.parse(raw) as CourseSummary[];
  const structured = new Map(loadTopics().map((course) => [course.slug, course]));

  if (structured.size === 0) return courses;

  return courses.map((course) => {
    const topics = structured.get(course.slug);
    if (!topics) return course;
    return {
      ...course,
      title: topics.title || course.title,
      description: topics.description || course.description,
      topicCount: topics.topics.length,
      // Full list for course search; the reader/page caps what it renders.
      topics: topics.topics.map((topic) => topic.title),
    };
  });
}

export function getCourseMarkdown(slug: string): string | null {
  const file = path.join(DATA_DIR, "courses", `${slug}.md`);
  if (!fs.existsSync(file)) return null;
  return fs.readFileSync(file, "utf8") + "\n";
}

export function getCrops(): Crop[] {
  const raw = fs.readFileSync(path.join(DATA_DIR, "crops.json"), "utf8");
  return JSON.parse(raw) as Crop[];
}

export function getCropBySlug(slug: string): Crop | undefined {
  return getCrops().find((c) => c.slug === slug);
}